import Foundation
import XCTest

@testable import vz_macos

final class GuestBridgeProtocolTests: XCTestCase {
  private let codec = GuestBridgeProtocolCodec()
  private let vmID = "vm_01J00000000000000000000000"
  private let requestID = "req_01J00000000000000000000001"
  private let operationID = "op_01J00000000000000000000001"

  func testAcceptedGoldenHeadersRoundTripWithoutLeakingTokensIntoResponses() throws {
    // Independent accepted schema fixtures, not generated by the codec under test.
    let schema = URL(fileURLWithPath: #filePath)
      .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
      .deletingLastPathComponent().deletingLastPathComponent()
      .appendingPathComponent("schemas/guest-bridge/v1.schema.json")
    let document = try XCTUnwrap(
      JSONSerialization.jsonObject(with: Data(contentsOf: schema)) as? [String: Any])
    let examples = try XCTUnwrap(document["examples"] as? [[String: Any]])
    XCTAssertEqual(examples.count, 5)
    for example in examples {
      let payload = try JSONSerialization.data(withJSONObject: example)
      let message = try codec.decode(payload)
      let encoded = try codec.encode(message)
      XCTAssertEqual(try codec.decode(encoded), message)
      let output = try XCTUnwrap(
        JSONSerialization.jsonObject(with: encoded) as? [String: Any])
      XCTAssertEqual(Set(output.keys), Set(example.keys))
      XCTAssertEqual(output["protocol_version"] as? String, "gaovm.bridge.v1")
      XCTAssertEqual(message.correlation.vmId, vmID)
      XCTAssertEqual(message.correlation.requestId, requestID)
      XCTAssertEqual(message.correlation.driverGeneration, 8)
      if example["stream_kind"] as? String == "control" {
        XCTAssertNil(message.correlation.operationId)
        XCTAssertTrue(output["operation_id"] is NSNull)
      } else {
        XCTAssertEqual(message.correlation.operationId, operationID)
      }
      if example["kind"] as? String != "open" {
        XCTAssertNil(output["auth_token"])
      }
      XCTAssertFalse(String(describing: message).contains("test-only-generation-token"))
    }
  }

  func testRejectsDuplicateRawAndEscapedKeysBeforeNormalization() throws {
    let duplicates = [
      #""protocol_version":"gaovm.bridge.v1""#,
      #""kind":"open""#,
      #""vm_id":"vm_01J00000000000000000000000""#,
      #""driver_generation":8"#,
      #""request_id":"req_01J00000000000000000000001""#,
      #""operation_id":null"#,
      #""stream_kind":"control""#,
      #""auth_token":"test-only-generation-token""#,
      #""\u0061uth_token":"test-only-generation-token""#,
      #""\u0076m_id":"vm_01J00000000000000000000000""#,
      #""\u0070rotocol_version":"gaovm.bridge.v1""#,
    ]
    for duplicate in duplicates {
      let json = "{\(duplicate),\(openHeader.dropFirst())"
      XCTAssertThrowsError(try codec.decode(Data(json.utf8))) { error in
        XCTAssertEqual(error as? GuestBridgeProtocolError, .invalidHeader)
        XCTAssertFalse(String(describing: error).contains("test-only-generation-token"))
      }
    }
    // Escape syntax inside a value is not a second member key.
    let escaped = openHeader.replacingOccurrences(
      of: "test-only-generation-token", with: #"quote\" slash\\ escaped\u003a"#)
    XCTAssertNoThrow(try codec.decode(Data(escaped.utf8)))
  }

  func testRejectsInvalidBindingsAndNonContractFields() throws {
    let invalid = [
      "[]", "null", "true", "{}",
      openHeader.replacingOccurrences(of: "gaovm.bridge.v1", with: "gaovm.bridge.v2"),
      openHeader.replacingOccurrences(of: #""kind":"open""#, with: #""kind":"other""#),
      openHeader.replacingOccurrences(of: vmID, with: "vm_81J00000000000000000000000"),
      openHeader.replacingOccurrences(of: vmID, with: vmID.lowercased()),
      openHeader.replacingOccurrences(of: vmID, with: vmID + #"\n"#),
      openHeader.replacingOccurrences(of: requestID, with: "op_01J00000000000000000000001"),
      openHeader.replacingOccurrences(of: #""operation_id":null,"#, with: ""),
      openHeader.replacingOccurrences(
        of: #""operation_id":null"#, with: #""operation_id":"wrong""#),
      openHeader.replacingOccurrences(
        of: #""stream_kind":"control""#, with: #""stream_kind":"binary""#),
      openHeader.replacingOccurrences(
        of: #""stream_kind":"control""#, with: #""stream_kind":"other""#),
      openHeader.replacingOccurrences(
        of: #""auth_token":"test-only-generation-token""#, with: #""auth_token":null"#),
      openHeader.replacingOccurrences(
        of: #""auth_token":"test-only-generation-token""#, with: #""auth_token":[]"#),
      openHeader.replacingOccurrences(
        of: #""auth_token":"test-only-generation-token""#, with: #""auth_token":{"token":"x"}"#),
      openHeader.dropLast() + #", "port":10777}"#,
      openHeader.dropLast() + #", "path":null}"#,
      openHeader + "{}",
    ]
    for json in invalid { XCTAssertThrowsError(try codec.decode(Data(json.utf8))) }
    for generation in [
      "0", "-1", "true", #""8""#, "8.5", "9007199254740992",
      "9007199254740990.5", "8.0000000000001", "8." + String(repeating: "0", count: 100) + "1",
    ] {
      let json = openHeader.replacingOccurrences(
        of: #""driver_generation":8"#, with: #""driver_generation":\#(generation)"#)
      XCTAssertThrowsError(try codec.decode(Data(json.utf8)), "accepted generation \(generation)")
    }
    for bytes in [
      Data([0xff]), Data([0xef, 0xbb, 0xbf]) + Data(openHeader.utf8),
      try XCTUnwrap(openHeader.data(using: .utf16LittleEndian)),
    ] {
      XCTAssertThrowsError(try codec.decode(bytes))
    }
  }

  func testGenerationUsesExactIntegerValueWithoutNarrowingValidJSONNumbers() throws {
    for generation in [
      "8", "8.0", "8e0", "80e-1", "0.8e1",
      "8." + String(repeating: "0", count: 100), "8000e-0003",
    ] {
      let json = openHeader.replacingOccurrences(
        of: #""driver_generation":8"#, with: #""driver_generation":\#(generation)"#)
      XCTAssertEqual(try codec.decode(Data(json.utf8)).correlation.driverGeneration, 8)
    }
    let maximum = openHeader.replacingOccurrences(
      of: #""driver_generation":8"#, with: #""driver_generation":9007199254740991"#)
    XCTAssertEqual(
      try codec.decode(Data(maximum.utf8)).correlation.driverGeneration, 9_007_199_254_740_991)
  }

  func testHeaderAndTokenBoundsCountEncodedUTF8Bytes() throws {
    let payload = Data(openHeader.utf8)
    let atLimit = payload + Data(repeating: 32, count: 4096 - payload.count)
    XCTAssertNoThrow(try codec.decode(atLimit))
    XCTAssertThrowsError(try codec.decode(atLimit + Data([32])))
    XCTAssertThrowsError(try codec.decode(Data()))
    for (token, valid) in [
      ("", false), (String(repeating: "a", count: 512), true),
      (String(repeating: "a", count: 513), false), (String(repeating: "é", count: 256), true),
      (String(repeating: "é", count: 257), false),
    ] {
      let json = openHeader.replacingOccurrences(of: "test-only-generation-token", with: token)
      if valid {
        let message = try codec.decode(Data(json.utf8))
        XCTAssertEqual(try codec.decode(codec.encode(message)), message)
      } else {
        XCTAssertThrowsError(try codec.decode(Data(json.utf8)))
        let correlation = try codec.decode(payload).correlation
        XCTAssertThrowsError(try codec.encode(.open(correlation, authToken: token)))
      }
    }
  }

  private var openHeader: String {
    #"{"protocol_version":"gaovm.bridge.v1","kind":"open","vm_id":"\#(vmID)","driver_generation":8,"request_id":"\#(requestID)","operation_id":null,"stream_kind":"control","auth_token":"test-only-generation-token"}"#
  }
}
